def num(v):
    try:
        return float(str(v).replace(',','')) if v not in (None,'') else 0.0
    except:
        return 0.0

def action_val(items, kind, key=None):
    for it in (items or []):
        it=it or {}
        if it.get('action_type')==kind:
            return num(it.get(key)) if key and key in it else num(it.get('value'))
    return 0.0
